function startRun(){$('#garage-panel').classList.remove('open');$('#home-screen').classList.remove('active');$('#pause-screen').classList.remove('active');$('#result-screen').classList.remove('active');$('#level-screen').classList.remove('active');$('#game-screen').classList.add('active');const mapIndex=Math.floor(Math.random()*maps.length);buildEnvironment(mapIndex);$('#map-name').textContent=maps[mapIndex].name;$('#map-preview b').textContent=maps[mapIndex].name;buildVehicle();for(const e of enemiesLive)worldGroup.remove(e.mesh);enemiesLive=[];for(const b of bullets)worldGroup.remove(b.mesh);bullets=[];for(const p of pickups)worldGroup.remove(p.mesh);pickups=[];for(const p of particles)worldGroup.remove(p.mesh);particles=[];boss=null;$('#boss-bar').classList.add('hidden');elapsed=0;xp=0;level=1;xpNext=100;kills=0;runIron=0;wave=1;spawnTimer=.5;shotTimer=.2;mineTimer=0;damageFlash=0;playerData.weapon={gun:1};playerData.weaponCD={};playerData.health=playerData.maxHealth;playerData.boost=0;playerData.turbo=1+save.upgrades.velocidade*.045;playerData.armor=1+save.upgrades.vida*.035;playerData.damage=1+save.upgrades.dano*.09;playerData.magnet=10+save.upgrades.ima*2;specialReady=true;specialCooldown=0;driftOn=false;gameState='playing';$('#clock').textContent='00:00';$('#health-fill').style.width='100%';$('#health-text').textContent=Math.round(playerData.health);$('#level').textContent='01';$('#xp-fill').style.width='0%';$('#xp-text').textContent='0 / 100';$('#wave').textContent='01';$('#wave-type').textContent='PATRULHA';if(!localStorage.getItem('iron-tutorial-done')){tutorialUntil=20;tutorialIndex=0;showTutorial()}else{$('#tutorial-card').classList.add('hidden')}updateWeaponStrip();sound(180,.13,'triangle')}
function pauseGame(){if(gameState==='playing'){gameState='paused';$('#pause-screen').classList.add('active')}}function resumeGame(){if(gameState==='paused'){gameState='playing';$('#pause-screen').classList.remove('active');last=performance.now()}}
function finishRun(won=false){if(gameState==='result')return;gameState='result';$('#game-screen').classList.remove('active');$('#pause-screen').classList.remove('active');$('#level-screen').classList.remove('active');$('#result-screen').classList.add('active');const bonus=Math.floor(kills*.16+elapsed/22)+(won?120:0);runIron+=bonus;save.iron+=runIron;persist();$('#result-title').innerHTML=won?'VOCÊ DOMINOU<br><span>A TEMPESTADE.</span>':'A ESTRADA<br><span>CONTINUA.</span>';$('#result-copy').textContent=won?'O deserto conheceu seu nome.':'Você deixou sua marca no deserto.';$('#result-time').textContent=formatTime(elapsed);$('#result-kills').textContent=String(kills).padStart(3,'0');$('#result-level').textContent=String(level).padStart(2,'0');$('#result-iron').textContent='+'+runIron;sound(won?440:95,.35,won?'triangle':'sawtooth')}
function formatTime(v){const n=Math.floor(v);return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')}
function showTutorial(){const steps=[['ENCONTRE SEU RITMO','Use WASD ou o analógico para dirigir.'],['DERRAPE NA CURVA','Segure ESPAÇO ou o botão DRIFT para carregar o turbo.'],['SUCATA É SOBREVIVÊNCIA','Fragmentos próximos vêm até você. Colete para subir de nível.'],['SEU CAMINHÃO ATIRA SOZINHO','Foque em escapar. Use SHIFT ou habilidade especial no aperto.']];const i=Math.min(tutorialIndex,3);$('#tutorial-count').innerHTML='0'+(i+1)+' <i>/ 04</i>';$('#tutorial-title').textContent=steps[i][0];$('#tutorial-copy').textContent=steps[i][1];$('#tutorial-card').classList.remove('hidden')}
function levelUp(){level++;xp-=xpNext;xpNext=Math.floor(xpNext*1.18+18);gameState='level';$('#level').textContent=String(level).padStart(2,'0');showUpgradeCards()}
function showUpgradeCards(){const keys=Object.keys(upgrades).filter(k=>{const u=upgrades[k];if(u.kind==='weapon')return (playerData.weapon[k]||0)<5;return true});const cards=[];while(cards.length<3&&keys.length){const i=Math.floor(Math.random()*keys.length);cards.push(keys.splice(i,1)[0])}while(cards.length<3)cards.push(pick(['speed','armor','repair']));$('#upgrade-cards').innerHTML=cards.map((k,i)=>{const u=upgrades[k],rar=u.rarity;return `<button class="upgrade-card ${rar}" data-upgrade="${k}"><span class="card-rarity">${rar.toUpperCase()}</span><span class="card-level">${u.kind==='weapon'?(playerData.weapon[k]?'NV. '+(playerData.weapon[k]+1):'NOVA ARMA'):'MELHORIA'}</span><div class="card-icon">${u.icon}</div><h3>${u.title}</h3><p>${u.text}</p></button>`}).join('');$('#level-screen').classList.add('active')}
function applyUpgrade(k){const u=upgrades[k];if(u.kind==='weapon')playerData.weapon[k]=(playerData.weapon[k]||0)+1;else if(k==='speed')playerData.turbo*=1.12;else if(k==='armor'){playerData.armor*=1.1;playerData.health=Math.min(playerData.maxHealth,playerData.health+15)}else if(k==='magnet')playerData.magnet+=5;else if(k==='repair')playerData.health=Math.min(playerData.maxHealth,playerData.health+35);else if(k==='turbo')playerData.turbo*=1.18;else if(k==='luck')save.upgrades.sorte+=1;updateWeaponStrip();$('#level-screen').classList.remove('active');gameState='playing';if(xp>=xpNext)levelUp();sound(660,.1,'triangle')}
function updateWeaponStrip(){const active=Object.entries(playerData.weapon).filter(([,n])=>n>0);$('#weapon-strip').innerHTML=active.map(([k,n])=>`<div class="weapon-chip" title="${weaponDefs[k].name}">${weaponDefs[k].icon}<small>${n}</small></div>`).join('')}
function getTarget(range=60){let best=null,dist=range;for(const e of enemiesLive){const d=e.mesh.position.distanceTo(playerData.pos);if(d<dist){dist=d;best=e}}return best}
