function killEnemy(e){const idx=enemiesLive.indexOf(e);if(idx<0)return;enemiesLive.splice(idx,1);const pos=e.mesh.position.clone();worldGroup.remove(e.mesh);kills++;if(e.boss){boss=null;$('#boss-bar').classList.add('hidden');explosion(pos,13,100,0xff7846);if(elapsed<590){spawnPickup(pos,1,'supply');$('#toast').textContent='CHEFE ELIMINADO — A ROTA FINAL ESTÁ ABERTA';$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}else{finishRun(true)}}else{explosion(pos,e.type==='bomber'?4:1.6,e.type==='bomber'?45:0,e.type==='bomber'?0xff7041:0xdfa759);for(let n=0;n<e.loot;n++)spawnPickup(pos.clone().add(new THREE.Vector3(rand(-1,1),.3,rand(-1,1))),1);if(e.elite)spawnPickup(pos.clone().add(new THREE.Vector3(0,1,0)),1,'supply')}xp+=e.xp;if(xp>=xpNext&&gameState==='playing')levelUp()}

