function updateProjectiles(dt){
 for(let i=bullets.length-1;i>=0;i--){
  const b=bullets[i],g=b.mesh,previous=g.position.clone();
  g.position.addScaledVector(b.dir,b.speed*dt);b.life-=dt;
  if(b.kind==='rocket')g.rotation.y+=dt*8;
  let removed=false;
  if(b.kind==='enemy'){
   if(g.position.distanceTo(playerData.pos.clone().add(new THREE.Vector3(0,1,0)))<1.65){damagePlayer(b.damage,g.position.clone());removed=true}
  }else{
   const target=enemiesLive.find(e=>g.position.distanceTo(e.mesh.position.clone().add(new THREE.Vector3(0,e.boss?2:1,0)))<e.r+.45);
   if(target){
    if(b.kind==='rocket')explosion(g.position.clone(),5,b.damage,0xff884b);else hitEnemy(target,b.damage,b.kind!=='bullet');
    removed=true;
   }
  }
  if(!removed&&(b.life<=0||g.position.distanceTo(playerData.pos)>95||g.position.y<terrainY(g.position.x,g.position.z)-.2)){
   if(b.kind==='rocket')explosion(g.position.clone(),4,b.damage*.55,0xff884b);
   removed=true;
  }
  if(removed){worldGroup.remove(g);bullets.splice(i,1)}
 }
}
function updatePickups(dt){
 for(let i=pickups.length-1;i>=0;i--){
  const p=pickups[i],g=p.mesh;p.life-=dt;g.rotation.y+=dt*(p.type==='mine'?1.5:2.2);
  if(p.type==='mine'){
   const target=enemiesLive.find(e=>e.mesh.position.distanceTo(g.position)<4.2);
   if(target){explosion(g.position.clone(),5,p.damage||55,0xff9a4a);worldGroup.remove(g);pickups.splice(i,1);continue}
   if(p.life<=0){worldGroup.remove(g);pickups.splice(i,1)}
   continue;
  }
  const delta=playerData.pos.clone().add(new THREE.Vector3(0,1,0)).sub(g.position),dist=delta.length();
  if(dist<playerData.magnet&&dist>.01)g.position.addScaledVector(delta,Math.min(1,dt*(p.type==='supply'?3.2:4.5)));
  g.position.y=terrainY(g.position.x,g.position.z)+.12+Math.sin(elapsed*3+i)*.16;
  if(dist<1.9){
   if(p.type==='supply'){playerData.health=Math.min(playerData.maxHealth,playerData.health+22);runIron+=Math.max(1,p.amount);xp+=24;toast('SUPRIMENTOS RECUPERADOS · +24 XP')}
   else{runIron+=Math.max(1,p.amount);xp+=8;const label=$('#pickup-toast');label.textContent=`+${p.amount} FERRO`;label.classList.add('show');clearTimeout(label.timer);label.timer=setTimeout(()=>label.classList.remove('show'),650)}
   if(xp>=xpNext&&gameState==='playing')levelUp();worldGroup.remove(g);pickups.splice(i,1);sound(690,.045,'triangle',.07);continue;
  }
  if(p.life<=0){worldGroup.remove(g);pickups.splice(i,1)}
 }
}
function updateParticles(dt){
 for(let i=particles.length-1;i>=0;i--){
  const p=particles[i],g=p.mesh;p.life-=dt;
  if(p.expand){const t=1-clamp(p.life/p.max,0,1);g.scale.setScalar(1+t*2.2);g.material.opacity=clamp(p.life/p.max,0,1)}
  else if(g.isPointLight){g.intensity=Math.max(0,g.intensity*(p.life/p.max))}
  else{g.position.addScaledVector(p.vel,dt);p.vel.y-=p.gravity*dt;if(g.material&&'opacity'in g.material)g.material.opacity=clamp(p.life/p.max,0,1);if(g.isSprite)g.scale.multiplyScalar(1+dt*.3)}
  if(p.life<=0){worldGroup.remove(g);if(g.geometry)g.geometry.dispose();if(g.material){if(Array.isArray(g.material))g.material.forEach(m=>m.dispose());else g.material.dispose()}particles.splice(i,1)}
 }
}
function updateHUD(){
 const ratio=clamp(playerData.health/playerData.maxHealth,0,1),xpRatio=clamp(xp/xpNext,0,1);
 $('#health-fill').style.width=`${ratio*100}%`;$('#health-text').textContent=String(Math.max(0,Math.ceil(playerData.health)));
 $('#health-fill').style.background=ratio<.28?'#d94f3d':'';
 $('#xp-fill').style.width=`${xpRatio*100}%`;$('#xp-text').textContent=`${Math.floor(xp)} / ${xpNext}`;
 $('#level').textContent=String(level).padStart(2,'0');
 const shell=$('.screen-vignette');if(shell)shell.style.setProperty('--damage-flash',String(damageFlash));
 shake=Math.max(0,shake-.06);
}
